#include <stdint.h>
#include <stdio.h>

// Mandated stack and tohost
uint64_t _stack[512];
uint64_t * const _stack_top = _stack+512;
extern volatile uint64_t tohost;

// Dedicated M-mode stack for trap handler
uint64_t _m_stack[64]; // Small stack for trap handler
uint64_t * const _m_stack_top = _m_stack+64;

// Trap handler
void handle_trap(void) __attribute__((naked));
void handle_trap(void) {
    // Save general purpose registers that might be clobbered
    asm volatile(
        "csrrw sp, mscratch, sp;" // Atomically swap sp and mscratch. sp now points to M-mode stack.
        "sd ra, 0(sp);"           // Save ra
        "sd t0, 8(sp);"           // Save t0
        "sd t1, 16(sp);"          // Save t1
        // Add more registers if the trap handler or its callees use them.
        // For simple timing, this minimal set is usually sufficient.

        // Determine cause and advance mepc if necessary
        "csrr t0, mcause;"      // Read mcause
        "csrr t1, mepc;"        // Read mepc
        "li t2, 0x8;"           // Environment call from M-mode (ECALL instruction)
        "bne t0, t2, 1f;"       // If not M-ECALL, skip advancing mepc by 4
        "addi t1, t1, 4;"       // Advance mepc by 4 for ECALL to skip the ECALL instruction
        "1: csrw mepc, t1;"     // Write back (potentially updated) mepc

        // Restore saved registers
        "ld t1, 16(sp);"        // Restore t1
        "ld t0, 8(sp);"         // Restore t0
        "ld ra, 0(sp);"         // Restore ra
        "csrrw sp, mscratch, sp;" // Atomically swap sp and mscratch. sp now points to original stack.
        "mret;"                 // Return from M-mode trap
    );
}

// Function to flush TLB. This is a global sfence.vma with ASID and G (global) bits set to zero.
// This effectively invalidates all non-global entries in the current ASID.
void flush_tlb(void) {
    asm volatile ("sfence.vma zero, zero;");
}

// Read cycle counter
static inline uint64_t read_cycle(void) {
    uint64_t cycle;
    asm volatile ("rdcycle %0" : "=r" (cycle));
    return cycle;
}

// Delay function using NOPs for pipeline settling
void delay(int count) {
    for (int i = 0; i < count; i++) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;"); // 8 NOPs per iteration
    }
}

// Test pages. Use static to ensure they are in data segment and aligned to page boundary.
#define PAGE_SIZE 4096
#define DATA_OFFSET 0 // Access the first byte of the page

// Using page-aligned static arrays to represent distinct virtual pages.
// These will correspond to distinct physical pages due to identity mapping in bare-metal M-mode.
static volatile uint8_t pageA[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageB[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageC[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));

#define NUM_TRIALS 200 // Number of trials per condition. Total iterations = 200*2 = 400.
#define DELAY_ITERS 100 // Iterations for the NOP delay function (100 * 8 NOPs = 800 NOPs)

// Results arrays
uint64_t results_no_victim[NUM_TRIALS];
uint64_t results_with_victim[NUM_TRIALS];

// Main function
int main() {
    // Set up trap handler with the dedicated M-mode stack
    asm volatile("csrw mtvec, %0" :: "r"(&handle_trap));
    asm volatile("csrw mscratch, %0" :: "r"(_m_stack_top)); // Set mscratch to point to our M-mode stack

    // Initialize pages to ensure they are mapped and potentially dirty.
    // This access ensures page tables are set up for them, and physical frames are allocated.
    // (In bare metal identity mapping, this just means they're in RAM and accessible.)
    for (int i = 0; i < PAGE_SIZE; i++) {
        pageA[i] = (uint8_t)i;
        pageB[i] = (uint8_t)i;
        pageC[i] = (uint8_t)i;
    }

    printf("PTE Cache Contention Experiment\n");

    // Experiment without victim access (PTE cache hit for pageA)
    printf("--- No Victim Page Walk ---\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        // 1. Flush TLBs for A, B (and C implicitly if it were accessed later)
        flush_tlb();
        delay(DELAY_ITERS);

        // 2. Attacker primes PTW's 2-entry PTE cache with PTEs for pageA and pageB.
        // These accesses will cause TLB misses and trigger page walks,
        // loading PTEs for A and B into the PTW's 2-entry PTE cache.
        volatile uint8_t temp_a = pageA[DATA_OFFSET];
        delay(DELAY_ITERS); // Ensure pipeline settles after first page walk
        volatile uint8_t temp_b = pageB[DATA_OFFSET];
        delay(DELAY_ITERS); // Ensure pipeline settles after second page walk

        // At this point, the 2-entry PTE cache should contain PTE_A and PTE_B.

        // 3. Victim does NOT perform a page walk.
        // (Nothing explicitly done here, just let the state remain.)
        delay(DELAY_ITERS);

        // 4. Attacker measures access time for pageA.
        // This access should be a PTE cache HIT, resulting in a fast access time.
        uint64_t start_time = read_cycle();
        volatile uint8_t measure_a = pageA[DATA_OFFSET];
        uint64_t end_time = read_cycle();
        results_no_victim[i] = end_time - start_time;
        delay(DELAY_ITERS);
    }

    // Experiment with victim access (PTE cache miss for pageA)
    printf("--- With Victim Page Walk ---\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        // 1. Flush TLBs for A, B, C
        flush_tlb();
        delay(DELAY_ITERS);

        // 2. Attacker primes PTW's 2-entry PTE cache with PTEs for pageA and pageB.
        volatile uint8_t temp_a = pageA[DATA_OFFSET];
        delay(DELAY_ITERS);
        volatile uint8_t temp_b = pageB[DATA_OFFSET];
        delay(DELAY_ITERS);

        // At this point, the 2-entry PTE cache should contain PTE_A and PTE_B.

        // 3. Victim performs a page walk to pageC.
        // This access to pageC should trigger a page walk. Since the PTW's PTE cache
        // has only 2 entries, this third page walk will evict either PTE_A or PTE_B.
        // If it evicts PTE_A, the subsequent access to pageA by the attacker will be slow.
        volatile uint8_t temp_c = pageC[DATA_OFFSET];
        delay(DELAY_ITERS); // Ensure pipeline settles after victim's page walk

        // 4. Attacker measures access time for pageA.
        // This access *might* be a PTE cache MISS if PTE_A was evicted by PTE_C,
        // resulting in a slower access time due to a page walk.
        uint64_t start_time = read_cycle();
        volatile uint8_t measure_a = pageA[DATA_OFFSET];
        uint64_t end_time = read_cycle();
        results_with_victim[i] = end_time - start_time;
        delay(DELAY_ITERS);
    }

    // Print results
    printf("\nResults (cycles):\n");
    printf("No Victim Page Walk (Expected fast, PTE_A hit):\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu ", results_no_victim[i]);
    }
    printf("\n\n");

    printf("With Victim Page Walk (Expected slow for some, PTE_A miss if evicted):\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu ", results_with_victim[i]);
    }
    printf("\n\n");

    // Indicate simulation termination
    tohost = 1;
    while (1) {}

    return 0;
}

