// Root page table for SV39 (Level 2)
uint64_t L2_PAGE_TABLE[512] __attribute__((aligned(PAGE_SIZE)));

// Function to flush TLB. This is a global sfence.vma with ASID and G (global) bits set to zero.
void flush_tlb(void) {
    asm volatile ("sfence.vma zero, zero;");
}

// Read cycle counter
static inline uint64_t read_cycle(void) {
    uint64_t cycle;
    asm volatile ("rdcycle %0" : "=r" (cycle));
    return cycle;
}

// Read satp CSR
static inline uint64_t read_satp(void) {
    uint64_t satp_val;
    asm volatile ("csrr %0, satp" : "=r" (satp_val));
    return satp_val;
}

// Delay function using NOPs for pipeline settling
void delay(int count) {
    for (int i = 0; i < count; i++) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;"); // 8 NOPs per iteration
    }
}

