    // Identity map 0x80000000 (typical program base) to 0x80000000 using a 1GB page.
    // This allows the program to continue executing as if it were physical addressing,
    // but now with virtual memory enabled.

    // PTE format for 1GB page: [PPN | RsW | Rsv | D | A | G | U | X | W | R | V]
    // Flags: V=1 (Valid), R=1 (Read), W=1 (Write), X=1 (Execute), A=1 (Accessed), D=1 (Dirty), G=1 (Global)
    // U=0 (Supervisor/Machine mode access only)
    uint64_t pte_flags = (1ULL << 0) | // V
                         (1ULL << 1) | // R
                         (1ULL << 2) | // W
                         (1ULL << 3) | // X
                         (0ULL << 4) | // U (Set to 0 for M-mode only access)
                         (1ULL << 6) | // G (Global, useful for kernel pages)
                         (1ULL << 7) | // A (Accessed)
                         (1ULL << 8);  // D (Dirty)

