    // satp = (MODE << 60) | (ASID << 44) | PPN_OF_ROOT_PAGE_TABLE
    // MODE = 8 for SV39
    // ASID = 0 (no ASID management for bare-metal, single address space)
    // PPN_OF_ROOT_PAGE_TABLE = (physical address of L2_PAGE_TABLE) >> 12
    uint64_t root_pt_ppn = ((uint64_t)L2_PAGE_TABLE) >> 12;
    uint64_t satp_val = (8ULL << 60) | root_pt_ppn; // MODE=8 (SV39) | PPN
