uint64_t * const _stack_top = _stack+512;
extern volatile uint64_t tohost;

// Dedicated M-mode stack for trap handler
uint64_t _m_stack[64]; // Small stack for trap handler
uint64_t * const _m_stack_top = _m_stack+64;

// Trap handler
void handle_trap(void) __attribute__((naked));
void handle_trap(void) {
    // Save general purpose registers that might be clobbered
    asm volatile(
        "csrrw sp, mscratch, sp;" // Atomically swap sp and mscratch. sp now points to M-mode stack.
        "sd ra, 0(sp);"           // Save ra
        "sd t0, 8(sp);"           // Save t0
        "sd t1, 16(sp);"          // Save t1

        // Determine cause and advance mepc if necessary
        "csrr t0, mcause;"      // Read mcause
        "csrr t1, mepc;"        // Read mepc
        "li t2, 0x8;"           // Environment call from M-mode (ECALL instruction)
        "bne t0, t2, 1f;"       // If not M-ECALL, skip advancing mepc by 4
        "addi t1, t1, 4;"       // Advance mepc by 4 for ECALL to skip the ECALL instruction
        "1: csrw mepc, t1;"     // Write back (potentially updated) mepc

        // No direct printf in naked assembly function.
        // If a page fault or other trap occurs, its mcause will be logged to simulation log.

        // Restore saved registers
        "ld t1, 16(sp);"        // Restore t1
        "ld t0, 8(sp);"         // Restore t0
        "ld ra, 0(sp);"         // Restore ra
        "csrrw sp, mscratch, sp;" // Atomically swap sp and mscratch. sp now points to original stack.
        "mret;"                 // Return from M-mode trap
    );
}

// Test pages. Use static to ensure they are in data segment and aligned to page boundary.
#define PAGE_SIZE 4096
#define DATA_OFFSET 0 // Access the first byte of the page

// Page tables
// Root page table for SV39 (Level 2)
uint64_t L2_PAGE_TABLE[512] __attribute__((aligned(PAGE_SIZE)));

// Function to flush TLB. This is a global sfence.vma with ASID and G (global) bits set to zero.
void flush_tlb(void) {
    asm volatile ("sfence.vma zero, zero;");
}

// Read cycle counter
static inline uint64_t read_cycle(void) {
    uint64_t cycle;
    asm volatile ("rdcycle %0" : "=r" (cycle));
    return cycle;
}

// Read satp CSR
static inline uint64_t read_satp(void) {
    uint64_t satp_val;
    asm volatile ("csrr %0, satp" : "=r" (satp_val));
    return satp_val;
}

// Delay function using NOPs for pipeline settling
void delay(int count) {
    for (int i = 0; i < count; i++) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;"); // 8 NOPs per iteration
    }
}

// Using page-aligned static arrays to represent distinct virtual pages.
static volatile uint8_t pageA[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageB[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageC[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageD[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE))); // For positive control

#define NUM_TRIALS 200 // Number of trials per condition. Total iterations = 200*2 = 400.
#define DELAY_ITERS 200 // Iterations for the NOP delay function (200 * 8 NOPs = 1600 NOPs)

// Results arrays
uint64_t results_no_victim[NUM_TRIALS];
uint64_t results_with_victim[NUM_TRIALS];
uint64_t pc_first_access[NUM_TRIALS]; // Positive control: first access after flush
uint64_t pc_second_access[NUM_TRIALS]; // Positive control: second access (TLB hit)

// Function to set up page tables and enable MMU
void setup_mmu() {
    // Identity map 0x80000000 (typical program base) to 0x80000000 using a 1GB page.
    // This allows the program to continue executing as if it were physical addressing,
    // but now with virtual memory enabled.

    // PTE format for 1GB page: [PPN | RsW | Rsv | D | A | G | U | X | W | R | V]
    // Flags: V=1 (Valid), R=1 (Read), W=1 (Write), X=1 (Execute), A=1 (Accessed), D=1 (Dirty), G=1 (Global)
    // U=0 (Supervisor/Machine mode access only)
    uint64_t pte_flags = (1ULL << 0) | // V
                         (1ULL << 1) | // R
                         (1ULL << 2) | // W
                         (1ULL << 3) | // X
                         (0ULL << 4) | // U (Set to 0 for M-mode only access)
                         (1ULL << 6) | // G (Global, useful for kernel pages)
                         (1ULL << 7) | // A (Accessed)
                         (1ULL << 8);  // D (Dirty)

    // PPN for 0x80000000 1GB page is 0x2 (0x80000000 physical address / 1GB page size (0x40000000))
    // In SV39, for a 1GB page, the PPN is (PA >> 30). This PPN goes into bits 53:28 of the PTE.
    uint64_t ppn_val = 0x2ULL; 
    uint64_t level2_pte = (ppn_val << 28) | pte_flags; // PPN for 1GB page

    // Virtual address 0x80000000 for SV39 has VPN[2] = 0x2 (0x80000000 >> 30)
    L2_PAGE_TABLE[2] = level2_pte;

    // Flush TLB and instruction cache before activating MMU
    flush_tlb();
    asm volatile ("fence.i");

    // Enable SV39 mode by writing to satp CSR
    // satp = (MODE << 60) | (ASID << 44) | PPN_OF_ROOT_PAGE_TABLE
    // MODE = 8 for SV39
    // ASID = 0 (no ASID management for bare-metal, single address space)
    // PPN_OF_ROOT_PAGE_TABLE = (physical address of L2_PAGE_TABLE) >> 12
    uint64_t root_pt_ppn = ((uint64_t)L2_PAGE_TABLE) >> 12;
    uint64_t satp_val = (8ULL << 60) | root_pt_ppn; // MODE=8 (SV39) | PPN
    asm volatile ("csrw satp, %0" :: "r"(satp_val));

    // sfence.vma after changing satp to make new page tables effective
    flush_tlb(); 
    // Also flush ICache, as execution path might have changed due to VM enabling.
    asm volatile ("fence.i"); 
}

// Main function
int main() {
    // Declare variables once outside loops
    uint64_t start_time, end_time;
    volatile uint8_t val1, val2, temp_a, temp_b, temp_c, measure_a;
    uint64_t satp_value;

    // Set up trap handler with the dedicated M-mode stack
    asm volatile("csrw mtvec, %0" :: "r"(&handle_trap));
    asm volatile("csrw mscratch, %0" :: "r"(_m_stack_top)); // Set mscratch to point to our M-mode stack

    printf("PTE Cache Contention Experiment\n");

    // --- SETUP MMU ---
    printf("Setting up MMU and enabling virtual memory (SV39)...\n");
    setup_mmu();
    satp_value = read_satp();
    printf("SATP CSR value after setup: 0x%lx\n", satp_value);
    if ((satp_value >> 60) != 8) { // Check if SV39 mode is enabled (MODE == 8)
        printf("ERROR: Virtual memory (SV39) could not be enabled. Exiting.\n");
        tohost = 1;
        while (1) {}
    }
    printf("Virtual memory (SV39) enabled. Proceeding with tests.\n");

    // Initialize pages to ensure they are mapped and accessible.
    for (int i = 0; i < PAGE_SIZE; i++) {
        pageA[i] = (uint8_t)i;
        pageB[i] = (uint8_t)i;
        pageC[i] = (uint8_t)i;
        pageD[i] = (uint8_t)i;
    }

    // --- PAGE WALK POSITIVE CONTROL ---
    printf("\n--- Positive Control: Page Walk Latency ---\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        flush_tlb();
        delay(DELAY_ITERS);

        start_time = read_cycle();
        val1 = pageD[DATA_OFFSET]; // First access, should be slow (page walk)
        end_time = read_cycle();
        pc_first_access[i] = end_time - start_time;
        delay(DELAY_ITERS);

        start_time = read_cycle();
        val2 = pageD[DATA_OFFSET]; // Second access, should be fast (TLB hit)
        end_time = read_cycle();
        pc_second_access[i] = end_time - start_time;
        delay(DELAY_ITERS);

        // Dummy uses to prevent optimization
        if (val1 == 0xFF) printf("Dummy\n");
        if (val2 == 0xFF) printf("Dummy\n");
    }

    // Experiment without victim access (PTE cache hit for pageA)
    printf("\n--- No Victim Page Walk (Main Experiment) ---\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        // 1. Flush TLBs for A, B, C (D implicitly if it was accessed earlier)
        flush_tlb();
        delay(DELAY_ITERS);

        // 2. Attacker primes PTW's 2-entry PTE cache with PTEs for pageA and pageB.
        temp_a = pageA[DATA_OFFSET];
        delay(DELAY_ITERS); // Ensure pipeline settles after first page walk
        temp_b = pageB[DATA_OFFSET];
        delay(DELAY_ITERS); // Ensure pipeline settles after second page walk

        // At this point, the 2-entry PTE cache should contain PTE_A and PTE_B.

        // 3. Victim does NOT perform a page walk. (No access to pageC)
        delay(DELAY_ITERS);

        // 4. Attacker measures access time for pageA.
        start_time = read_cycle();
        measure_a = pageA[DATA_OFFSET];
        end_time = read_cycle();
        results_no_victim[i] = end_time - start_time;
        delay(DELAY_ITERS);

        // Dummy uses to prevent optimization
        if (temp_a == 0xFF) printf("Dummy\n");
        if (temp_b == 0xFF) printf("Dummy\n");
        if (measure_a == 0xFF) printf("Dummy\n");
    }

    // Experiment with victim access (PTE cache miss for pageA)
    printf("\n--- With Victim Page Walk (Main Experiment) ---\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        // 1. Flush TLBs for A, B, C
        flush_tlb();
        delay(DELAY_ITERS);

        // 2. Attacker primes PTW's 2-entry PTE cache with PTEs for pageA and pageB.
        temp_a = pageA[DATA_OFFSET];
        delay(DELAY_ITERS);
        temp_b = pageB[DATA_OFFSET];
        delay(DELAY_ITERS);

        // At this point, the 2-entry PTE cache should contain PTE_A and PTE_B.

        // 3. Victim performs a page walk to pageC.
        temp_c = pageC[DATA_OFFSET];
        delay(DELAY_ITERS); // Ensure pipeline settles after victim's page walk

        // 4. Attacker measures access time for pageA.
        start_time = read_cycle();
        measure_a = pageA[DATA_OFFSET];
        end_time = read_cycle();
        results_with_victim[i] = end_time - start_time;
        delay(DELAY_ITERS);

        // Dummy uses to prevent optimization
        if (temp_a == 0xFF) printf("Dummy\n");
        if (temp_b == 0xFF) printf("Dummy\n");
        if (temp_c == 0xFF) printf("Dummy\n");
        if (measure_a == 0xFF) printf("Dummy\n");
    }

    // Print results
    printf("\nResults (cycles):\n");
    printf("Positive Control - First Access (Page Walk Expected):\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu ", pc_first_access[i]);
    }
    printf("\n\n");

    printf("Positive Control - Second Access (TLB Hit Expected):\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu ", pc_second_access[i]);
    }
    printf("\n\n");

    printf("No Victim Page Walk (Expected fast, PTE_A hit):\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu ", results_no_victim[i]);
    }
    printf("\n\n");

    printf("With Victim Page Walk (Expected slow for some, PTE_A miss if evicted):\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu ", results_with_victim[i]);
    }
    printf("\n\n");

    // Indicate simulation termination
    tohost = 1;
    while (1) {}

    return 0;
}

