// Using page-aligned static arrays to represent distinct virtual pages.
static volatile uint8_t pageA[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageB[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageC[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE)));
static volatile uint8_t pageD[PAGE_SIZE] __attribute__((aligned(PAGE_SIZE))); // For positive control

#define NUM_TRIALS 200 // Number of trials per condition. Total iterations = 200*2 = 400.
#define DELAY_ITERS 500 // Increased NOP iterations for pipeline settling

// Results arrays
uint64_t results_no_victim[NUM_TRIALS];
uint64_t results_with_victim[NUM_TRIALS];
uint64_t pc_first_access[NUM_TRIALS]; // Positive control: first access after flush
uint64_t pc_second_access[NUM_TRIALS]; // Positive control: second access (TLB hit)

// Function to set up page tables and enable MMU
void setup_mmu() {
    // Clear all page tables
    for (int i = 0; i < 512; i++) {
        L0_PAGE_TABLE[i] = 0;
        L1_PAGE_TABLE[i] = 0;
        L2_PAGE_TABLE[i] = 0;
    }

    // PTE flags for leaf (4KB) pages: V R W X G A D
    // U=0 (M-mode only, since we are in M-mode)
    uint64_t pte_leaf_flags = (1ULL << 0) | // V
                              (1ULL << 1) | // R
                              (1ULL << 2) | // W
                              (1ULL << 3) | // X
                              (1ULL << 5) | // G
                              (1ULL << 6) | // A
                              (1ULL << 7);  // D

    // PTE flags for non-leaf (pointer) pages: V
    uint64_t pte_pointer_flags = (1ULL << 0); // V

    // 1. Map 1GB region (0x80000000-0xBFFFFFFF) using L2_PAGE_TABLE
    // The VPN[2] for 0x80000000 is (0x80000000 >> 30) = 0x2
    // L2_PAGE_TABLE[2] will point to L1_PAGE_TABLE
    L2_PAGE_TABLE[2] = (((uint64_t)L1_PAGE_TABLE >> 12) << 10) | pte_pointer_flags;

    // 2. Map 2MB region (0x80000000-0x801FFFFF) within L1_PAGE_TABLE
    // The VPN[1] for 0x80000000 is ((0x80000000 >> 21) & 0x1FF) = 0x0
    // L1_PAGE_TABLE[0] will point to L0_PAGE_TABLE
    L1_PAGE_TABLE[0] = (((uint64_t)L0_PAGE_TABLE >> 12) << 10) | pte_pointer_flags;

    // 3. Map individual 4KB pages within L0_PAGE_TABLE
    // Get actual physical addresses of the pages (which are same as their static addresses)
    uint64_t pa_pageA = (uint64_t)pageA;
    uint64_t pa_pageB = (uint64_t)pageB;
    uint64_t pa_pageC = (uint64_t)pageC;
    uint64_t pa_pageD = (uint64_t)pageD;

    // Calculate VPN[0] for each page. VPN[0] = (VA >> 12) & 0x1FF
    L0_PAGE_TABLE[(pa_pageA >> 12) & 0x1FF] = ((pa_pageA >> 12) << 10) | pte_leaf_flags;
    L0_PAGE_TABLE[(pa_pageB >> 12) & 0x1FF] = ((pa_pageB >> 12) << 10) | pte_leaf_flags;
    L0_PAGE_TABLE[(pa_pageC >> 12) & 0x1FF] = ((pa_pageC >> 12) << 10) | pte_leaf_flags;
    L0_PAGE_TABLE[(pa_pageD >> 12) & 0x1FF] = ((pa_pageD >> 12) << 10) | pte_leaf_flags;

    // Flush TLB and instruction cache before activating MMU
    flush_tlb();
    asm volatile ("fence.i");

    // Enable SV39 mode by writing to satp CSR
    // satp = (MODE << 60) | (ASID << 44) | PPN_OF_ROOT_PAGE_TABLE
    // MODE = 8 for SV39
    // ASID = 0 (no ASID management for bare-metal, single address space)
    // PPN_OF_ROOT_PAGE_TABLE = (physical address of L2_PAGE_TABLE) >> 12
    uint64_t root_pt_ppn = ((uint64_t)L2_PAGE_TABLE) >> 12;
    uint64_t satp_val = (8ULL << 60) | root_pt_ppn; // MODE=8 (SV39) | PPN
    asm volatile ("csrw satp, %0" :: "r"(satp_val));

    // sfence.vma after changing satp to make new page tables effective
    flush_tlb(); 
    // Also flush ICache, as execution path might have changed due to VM enabling.
    asm volatile ("fence.i"); 
}

